CREATE TABLE "admin_biometric_recovery_requests" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "admin_biometric_recovery_requests_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"admin_user_id" integer NOT NULL,
	"admin_session_id" integer,
	"token_hash" varchar(64) NOT NULL,
	"status" varchar(24) DEFAULT 'pending' NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"consumed_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "admin_biometric_recovery_requests_token_hash_unique" UNIQUE("token_hash"),
	CONSTRAINT "admin_biometric_recovery_status_check" CHECK ("status" IN ('pending', 'completed', 'cancelled'))
);
ALTER TABLE "admin_biometric_recovery_requests" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "admin_biometric_recovery_requests" ADD CONSTRAINT "admin_biometric_recovery_requests_admin_user_id_admin_users_id_fk" FOREIGN KEY ("admin_user_id") REFERENCES "public"."admin_users"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "admin_biometric_recovery_requests" ADD CONSTRAINT "admin_biometric_recovery_requests_admin_session_id_admin_sessions_id_fk" FOREIGN KEY ("admin_session_id") REFERENCES "public"."admin_sessions"("id") ON DELETE set null ON UPDATE no action;
CREATE INDEX "admin_biometric_recovery_user_status_idx" ON "admin_biometric_recovery_requests" USING btree ("admin_user_id","status","expires_at");
